export const TERRAIN_TEMPLATES = RAW;
export const TERRAIN_COUNT = 20;
export const WORLD_ORIGIN_X = 320;

function templateFor(id) {
  return RAW[Math.max(0, Math.min(RAW.length - 1, Math.floor(id || 1) - 1))];
}

function column(template, localX) {
  if (!template || localX < 0 || localX > template.width) return [];
  const values = template.slices;
  const position = localX / template.width * (values.length - 1);
  const index = Math.min(values.length - 1, Math.floor(position));
  const a = values[index], b = values[Math.min(index + 1, values.length - 1)];
  // A topology change marks a real ledge, gap, or vertical cliff; blending
  // between different interval counts would introduce false diagonal walls.
  const disconnected = a.length !== b.length || a.some((y, i) =>
    i % 2 === 1 && Math.max(y, b[i]) > Math.min(a[i + 1], b[i + 1]) + 2);
  if (disconnected) return (position - index < .5 ? a : b).slice(1);
  const t = position - index;
  return a.slice(1).map((y, i) => y + (b[i + 1] - y) * t);
}

function groundGuide(template, localX) {
  const dots = Object.values(template.dots).slice().sort((a, b) => a[0] - b[0]);
  let a = dots[0], b = dots.at(-1);
  for (let i = 1; i < dots.length; i++) {
    if (localX <= dots[i][0]) { a = dots[i - 1]; b = dots[i]; break; }
  }
  const t = Math.max(0, Math.min(1, (localX - a[0]) / Math.max(.001, b[0] - a[0])));
  return a[1] + (b[1] - a[1]) * t + 48;
}

/** Native center coordinates in; world coordinates out. Adds the native 320px
 * horizontal stage origin, with no vertical shift. .x is collision left edge;
 * .y is the platform root Y, NOT its surface. Native centers stay available for
 * the original two-platform recycle and spacing rules. */
export function createPlatform(templateId, nativeCenterX, nativeCenterY, seed = .5) {
  const template = templateFor(templateId);
  const platform = {
    templateId: template.id, template, nativeCenterX, nativeCenterY,
    centerX: nativeCenterX + WORLD_ORIGIN_X, centerY: nativeCenterY,
    x: nativeCenterX + WORLD_ORIGIN_X + template.minX,
    y: nativeCenterY, width: template.width,
    layoutWidth: template.layoutWidth || template.width, seed,
  };
  platform.points = template.slices.map(slice => ({ x: slice[0], y: lane(template, slice[0], slice.slice(1))?.[0] ?? null }));
  platform.dots = Object.fromEntries(Object.entries(template.dots).map(([key, p]) => [key, {
    x: platform.x + p[0], y: platform.y + p[1],
  }]));
  return platform;
}

function lane(template, localX, values, nearY) {
  if (!values.length) return null;
  const target = nearY ?? groundGuide(template, localX);
  let selected = null, distance = Infinity;
  for (let i = 0; i + 1 < values.length; i += 2) {
    const next = Math.abs(values[i] - target);
    if (next < distance) { distance = next; selected = [values[i], values[i + 1]]; }
  }
  return selected;
}

function nativeTemplate(platform) {
  return platform.template || (platform.templateId === undefined ? null : templateFor(platform.templateId));
}

// Controlled flat/sloped fixtures also work without a native template.
function fixtureSurface(platform, worldX) {
  if (worldX < platform.x || worldX > platform.x + platform.width) return null;
  const points = platform.points || [{ x: 0, y: 0 }, { x: platform.width, y: 0 }];
  const x = worldX - platform.x;
  for (let i = 1; i < points.length; i++) if (x <= points[i].x) {
    if (points[i - 1].y === null || points[i].y === null) return null;
    const a = points[Math.max(0, i - 2)].y, b = points[i - 1].y;
    const c = points[i].y, d = points[Math.min(points.length - 1, i + 1)].y;
    const t = (x - points[i - 1].x) / Math.max(.001, points[i].x - points[i - 1].x);
    return platform.y + (2 * b + (-a + c) * t + (2 * a - 5 * b + 4 * c - d) * t * t + (-a + 3 * b - 3 * c + d) * t * t * t) / 2;
  }
  return platform.y + points.at(-1).y;
}

/** All solid [top,bottom] spans at a world X, in world Y coordinates. */
export function solidIntervals(platform, worldX) {
  const template = nativeTemplate(platform);
  if (!template) {
    const top = fixtureSurface(platform, worldX);
    return top === null ? [] : [[top, platform.bottom ?? 10000]];
  }
  const values = column(template, worldX - platform.x), result = [];
  for (let i = 0; i + 1 < values.length; i += 2) result.push([platform.y + values[i], platform.y + values[i + 1]]);
  return result;
}

/** Native-style point collision: ceilings and undersides are solid too. */
export function solidAt(platform, worldX, worldY) {
  const template = nativeTemplate(platform);
  if (!template) {
    const top = fixtureSurface(platform, worldX);
    return top !== null && worldY >= top && worldY <= (platform.bottom ?? 10000);
  }
  const localY = worldY - platform.y, values = column(template, worldX - platform.x);
  for (let i = 0; i + 1 < values.length; i += 2) {
    if (localY >= values[i] && localY <= values[i + 1]) return true;
  }
  return false;
}

/** Main walkable lane by default; optional nearY selects the nearest shelf top.
 * Returns null outside a platform or in an internal gap. */
export function surfaceY(platform, worldX, nearY) {
  const template = nativeTemplate(platform);
  if (!template) return fixtureSurface(platform, worldX);
  const localX = worldX - platform.x;
  const span = lane(template, localX, column(template, localX), nearY === undefined ? undefined : nearY - platform.y);
  return span ? platform.y + span[0] : null;
}

/** Underside of the same lane selected by surfaceY. For ceiling rendering or
 * collision use solidIntervals/solidAt, which include every disconnected span. */
export function undersideY(platform, worldX, nearY) {
  const template = nativeTemplate(platform);
  if (!template) return fixtureSurface(platform, worldX) === null ? null : (platform.bottom ?? 10000);
  const localX = worldX - platform.x;
  const span = lane(template, localX, column(template, localX), nearY === undefined ? undefined : nearY - platform.y);
  return span ? platform.y + span[1] : null;
}

export function terrainTemplate(id) { return templateFor(id); }
